//! Workspace identity for per-workspace canonical state: one key per folder, however its path is spelled.
//! The key is the folder's canonical path (links and `..` resolved by the file system when it exists), without Windows'
//! `\\?\` prefix, with forward slashes and — on Windows, whose paths ignore case — lower-cased, so `C:\Projects\App`,
//! `c:/projects/app/` and `C:\Projects\.\App` are one workspace. The original spelling is kept apart for display.

use std::path::{Path, PathBuf};

/// The identity of an open folder. Never a display name, never generated by a page.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct WorkspaceKey(String);

impl WorkspaceKey {
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

fn without_verbatim(path: &Path) -> PathBuf {
    let text = path.to_string_lossy();
    match text.strip_prefix(r"\\?\") {
        Some(rest) if !rest.starts_with("UNC\\") => PathBuf::from(rest),
        _ => path.to_path_buf(),
    }
}

/// The key of the folder at `path` (resolved through the file system when it exists).
pub fn workspace_key(path: &Path) -> WorkspaceKey {
    let resolved = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    key_of_spelling(&without_verbatim(&resolved))
}

/// The key of an already resolved path: separators unified, trailing separators dropped, case folded on Windows.
fn key_of_spelling(path: &Path) -> WorkspaceKey {
    let mut text = path.to_string_lossy().replace('\\', "/");
    while text.len() > 1 && text.ends_with('/') && !text.ends_with(":/") {
        text.pop();
    }
    if cfg!(windows) {
        text = text.to_lowercase();
    }
    WorkspaceKey(text)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn one_folder_is_one_key_however_it_is_spelled() {
        let temp = tempfile::tempdir().unwrap();
        let folder = temp.path().join("My Project");
        std::fs::create_dir_all(folder.join("src")).unwrap();
        let plain = workspace_key(&folder);
        assert_eq!(workspace_key(&folder.join("src").join("..")), plain);
        assert_eq!(
            workspace_key(&PathBuf::from(format!("{}/", folder.display()))),
            plain
        );
        if cfg!(windows) {
            let upper = PathBuf::from(folder.to_string_lossy().to_uppercase());
            assert_eq!(workspace_key(&upper), plain);
            assert!(!plain.as_str().contains('\\'), "{}", plain.as_str());
        }
        assert!(plain.as_str().ends_with("my project") || plain.as_str().ends_with("My Project"));
    }

    #[test]
    fn different_folders_have_different_keys_and_a_missing_folder_still_has_one() {
        let temp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(temp.path().join("a")).unwrap();
        std::fs::create_dir_all(temp.path().join("b")).unwrap();
        assert_ne!(
            workspace_key(&temp.path().join("a")),
            workspace_key(&temp.path().join("b"))
        );
        let missing = workspace_key(&temp.path().join("gone"));
        assert!(missing.as_str().ends_with("/gone"));
    }

    #[test]
    fn a_drive_root_keeps_its_separator() {
        if cfg!(windows) {
            assert_eq!(key_of_spelling(Path::new(r"C:\")).as_str(), "c:/");
        }
    }
}
